"""Build an inactive informed author candidate from preserved complete cases.
Scientific FIRST predates this builder. This script grants no independent gate.
"""
import copy, hashlib, json
from pathlib import Path
from datetime import datetime, timezone
OWN=Path(__file__).resolve().parents[1]
REPO=next(p for p in OWN.parents if (p/'AGENTS.md').exists())
OLD=REPO/'curricula/DE/Gymnasium/quality/goal-evidence/2026-10-12/chemie-carbonyl-pharmacy15-current231-scientific-author-20261013-v1/author'
def load(p):return json.loads(p.read_text())
def write(n,x):
 p=OWN/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def art(p):return {'path':str(p.relative_to(REPO)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}
first=load(OWN/'FIRST.author15.material-science.original.json')
assert hashlib.sha256((OWN/'FIRST.author15.material-science.original.json').read_bytes()).hexdigest()=='c5ad6d1941f54e98aeafcfe974be1eb761b7ea5c03ae972d853dd52cd097dc56'
prior=load(OLD/'whole30.expanded-cases.author.json');cases=copy.deepcopy(prior['cases']);by={x['caseId']:x for x in cases};profiles=copy.deepcopy(load(OLD/'whole15.profile-payloads.author.json')['profiles'])
# A targeted case update changes the actual asked clauses and their literal rubric/coverage joins together.
def update(cid,dataDe,dataEn,changes):
 c=by[cid];c['dataDe']=dataDe;c['dataEn']=dataEn
 for idx,v in changes.items():
  de,en,ansde,ansen=v;r=c['rubric'][idx];r.update(taskClauseDe=de,taskClauseEn=en,criterionDe=ansde,criterionEn=ansen)
 for lang,label,heading in [('De','Daten und Bedingungen:','Aufgaben:'),('En','Data and conditions:','Tasks:')]:
  c['task'+lang]=label+'\n'+c['data'+lang]+'\n'+heading+'\n'+'\n'.join(str(i+1)+'. '+r['taskClause'+lang] for i,r in enumerate(c['rubric']))
  c['modelAnswer'+lang]='\n'.join(str(i+1)+'. '+r['criterion'+lang] for i,r in enumerate(c['rubric']))
 for cov,r in zip(c['expectationCoverage'],c['rubric']):
  for lang in ['De','En']:cov['observableTaskClause'+lang]=r['taskClause'+lang]
 c['dataOrigin']='Original fictional teaching quantities plus separately dated official-source research context; no learner, lab or clinical observation in this author packet'
